const game = new GF.Game({
  id: 'titan-core-reforged',
  title: 'Titan Core: Reforged',
  width: 960,
  height: 540,
  palette: ['#0f0f0f', '#ff3e00', '#00ffe0', '#ffffff'],
  background: '#0f0f0f',
});

class Player {
  constructor() {
    this.x = game.W / 2;
    this.y = game.H / 2;
    this.size = 20;
    this.speed = 200;
    this.color = '#00ffe0';
    this.health = 100;
    this.attackCooldown = 0;
  }

  update(dt) {
    const { keys } = game.input;
    if (keys['ArrowUp'] || keys['KeyW']) this.y -= this.speed * dt;
    if (keys['ArrowDown'] || keys['KeyS']) this.y += this.speed * dt;
    if (keys['ArrowLeft'] || keys['KeyA']) this.x -= this.speed * dt;
    if (keys['ArrowRight'] || keys['KeyD']) this.x += this.speed * dt;

    this.x = GF.math.clamp(this.x, this.size, game.W - this.size);
    this.y = GF.math.clamp(this.y, this.size, game.H - this.size);

    if (game.input.pressed('Space') && this.attackCooldown <= 0) {
      this.attack();
      this.attackCooldown = 0.5;
    }

    this.attackCooldown = Math.max(0, this.attackCooldown - dt);
  }

  attack() {
    game.shake(5, 0.2);
    game.hitStop(0.1);
    GF.Sfx.beep({ freq: 400, dur: 0.1, vol: 0.5, type: 'square' });
    for (const titan of game.currentScene.titans) {
      if (GF.math.dist(this.x, this.y, titan.x, titan.y) < this.size + titan.size) {
        titan.health -= 20;
        if (titan.health <= 0) {
          game.addScore(10);
          game.burst(titan.x, titan.y, { count: 20, speed: 100, size: 5, life: 1, colors: ['#ff3e00', '#ffffff'], gravity: 100 });
          game.currentScene.titans = game.currentScene.titans.filter(t => t !== titan);
          game.flash('#00ffe0', 0.5);
          GF.Sfx.noise({ dur: 0.3, vol: 0.5 });
        }
      }
    }
  }

  draw(ctx) {
    ctx.fillStyle = this.color;
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.size, 0, GF.math.TAU);
    ctx.fill();
  }
}

class Titan {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.size = 50;
    this.health = 100;
    this.color = '#ff3e00';
  }

  update(dt) {
    // Titan AI logic here
  }

  draw(ctx) {
    ctx.fillStyle = this.color;
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.size, 0, GF.math.TAU);
    ctx.fill();
  }
}

class GameScene {
  init() {
    this.player = new Player();
    this.titans = [new Titan(game.W / 3, game.H / 3), new Titan(2 * game.W / 3, 2 * game.H / 3)];
  }

  reset() {
    this.init();
  }

  update(dt) {
    this.player.update(dt);
    for (const titan of this.titans) {
      titan.update(dt);
    }
  }

  draw(ctx) {
    this.player.draw(ctx);
    for (const titan of this.titans) {
      titan.draw(ctx);
    }
    GF.Draw.vignette(ctx, game.W, game.H, 0.5);
  }
}

game.add('play', new GameScene());
game.titleScreen({ subtitle: 'Press any key to start', onStart: () => game.go('play') });
